        addNavigateRule,
        addScopedMutationRule,
        appendStyleSheet,
        buildFeatureHealthReport,
        getSelectorAttributionSnapshot,
        withSelectorAttribution,
        buildOEmbedUrl,
        parseOEmbedMetadata,
        parseThumbnailUrl,
        resolveOriginalThumbnail,
