        configureNavigationRuntime,
        flushPendingStorageWrites,
        exportSelectorHealth: exportSelectorHealthReport,
        generateSettingsSchema,
        getCurrentPage,
        getCategoryHealthSnapshot,
        getLivePlaybackMetrics,
        getMainVideoElement,
        getMoviePlayerElement,
