        getRegisteredFeature,
        getActiveYouTubeClientVersion,
        getFeatureHealthSnapshot,
        getSelectorHealthSnapshot,
        getStoragePreloadError,
        getUrlParam,
        getUrlSearchParams,
        getVideoId,
        hasExtensionContext,
        injectStyle,
        installStorageChangeListener,
        installStorageFlushGuards,
        setStoragePersistentFailureHandler,
        isLiveChatFrame,
        isLiveChatPath,
        isShortsPagePath,
        isWatchPagePath,
        isTopLevelFrame,
        PageTypes,
        preloadExtensionState,
        registerFeature,
        probeCriticalSelectorSurfaces,
        removeMutationRule,
        removeNavigateRule,
        removeScopedMutationRule,
        runBudgetedElementBatch,
        setFeatureHealth,
        setCriticalSelectorCanarySnapshot,
        shouldBuildPrimaryUI,
        storageRead,
        storageReadJSON,
