    async function extensionFetchJson(details) {
        const req = {
            ...details,
            headers: {
                Accept: 'application/json',
                ...(details?.headers || {})
            }
        };
        const useRetry = appState?.settings?.apiRetryBackoff !== false;
        const response = useRetry
            ? await extensionRequestWithRetry(req)
            : await extensionRequestAsync(req);

        const notModified = details?.acceptNotModified === true && response?.status === 304;
        if (!response || (!notModified && (response.status < 200 || response.status >= 300))) {
            const error = new Error(`HTTP ${response?.status ?? 0}`);
            error.response = response;
            try {
                error.data = JSON.parse(response?.responseText || '');
            } catch (_) {
                // reason: error body may be plain text / HTML; leave error.data unset
            }
            throw error;
        }

        if (notModified) {
            return { response, data: null, notModified: true };
        }

        try {
            return {
                response,
                data: JSON.parse(response.responseText)
            };
        } catch (error) {
            const parseError = new Error(`Invalid JSON response from ${details?.url || 'extension request'}`);
            parseError.cause = error;
            parseError.response = response;
            throw parseError;
        }
    }

    async function extensionFetchText(details) {
        const req = { ...details };
        const useRetry = appState?.settings?.apiRetryBackoff !== false;
        const response = useRetry
            ? await extensionRequestWithRetry(req)
            : await extensionRequestAsync(req);

        if (!response || response.status < 200 || response.status >= 300) {
            const error = new Error(`HTTP ${response?.status ?? 0}`);
            error.response = response;
            throw error;
        }

        return {
            response,
            text: response.responseText || ''
        };
    }

