            _cardSelector: 'ytd-rich-item-renderer, ytd-video-renderer, ytd-grid-video-renderer',
            _hiddenMarker: 'ytkitMembersOnlyHidden',
            _displayMarker: 'ytkitMembersOnlyDisplay',
