                const transcript = globalThis.YTKitCore?.getTranscriptPanelElement?.(document) || null;
                const setVis = (el, vis) => { if (!el) return; el.style.display = vis ? '' : 'none'; };
                setVis(desc, which === 'desc');
                setVis(comments, which === 'comments');
